76	    /**
77	     * Syntactic check for an email address: a non-empty local part, a single {@code @}, and a
78	     * domain containing at least one dot, with no whitespace in any part.
79	     */
80	    private static final Pattern EMAIL_PATTERN = Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
81	
82	    /**
83	     * Email domains belonging to disposable/throwaway mail providers. An owner whose email domain
84	     * (the part after the {@code @}, compared case-insensitively) is listed here is rejected: such
85	     * addresses are not durable contact details. Entries are stored lower-cased.
86	     */
87	    private static final Set<String> DISPOSABLE_EMAIL_DOMAINS = Set.of(
88	        "mailinator.com",
89	        "tempmail.com",
90	        "guerrillamail.com");
91	
92	    /**
93	     * Dedicated audit logger. On a successful owner create an audit line is emitted here carrying the
94	     * new owner's id, customer code, registration date, membership level and membership number.
95	     */
96	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
97	
98	    /**
99	     * Common street-type abbreviations expanded during address normalization. Keys are the
100	     * upper-cased abbreviation as it appears as a whole whitespace-delimited token; values are the
101	     * expanded form it is replaced with.
102	     */
103	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
104	        "ST", "STREET",
105	        "RD", "ROAD",
106	        "AVE", "AVENUE");
107	
108	    /**
109	     * The maximum number of owners a single city may contain. Once a city holds this many owners it
110	     * is at capacity and cannot take any more.
111	     */
112	    private static final int CITY_CAPACITY = 50;
113	
114	    /**
115	     * The maximum number of owners that may be registered in a single day. Once this many owners
116	     * already carry today's {@code registrationDate}, the day's quota is exhausted and no further
117	     * owners can be created that day.
118	     */
119	    private static final int DAILY_OWNER_LIMIT = 100;
120	
121	    /**
122	     * The number of owners that may be registered on a single business day before a response starts
123	     * carrying a {@code bulkSignupWarning}. Once <em>more than</em> this many owners already carry the
124	     * current business day's {@code registrationDate}, that day's signups are flagged as unusually
125	     * high volume.
126	     */
127	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
128	
129	    /**
130	     * Fixed public holidays that the business-day roll skips over. A registration date that lands on
131	     * one of these dates is rolled forward to the next non-holiday business day, exactly as a weekend
132	     * date is rolled forward off a Saturday or Sunday.
133	     */
134	    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
135	        LocalDate.parse("2026-01-01"),
136	        LocalDate.parse("2026-01-26"),
137	        LocalDate.parse("2026-04-25"),
138	        LocalDate.parse("2026-12-25"),
