141	    /**
142	     * E.164 country codes mapped to the exact number of national (significant) digits a telephone for
143	     * that country must carry. For example {@code '+61'} (Australia) requires 9 national digits and
144	     * {@code '+1'} (NANP) requires 10. A country code listed here enforces that national-number length;
145	     * a number whose country code is not listed is accepted at any otherwise-valid E.164 length.
146	     */
147	    private static final Map<String, Integer> NATIONAL_NUMBER_LENGTHS = Map.of(
