154	     * region for the {@code customerCode} ({@link #regionForPostcode}). Each value is the inclusive
155	     * {@code {low, high}} 4-digit range for that region (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099). A
156	     * region that is not listed ({@code 'UNKNOWN'}) carries no range and accepts any 4-digit postcode.
157	     */
158	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
159	        "NSW", new int[] {2000, 2099},
160	        "VIC", new int[] {3000, 3099},
161	        "QLD", new int[] {4000, 4099});
162	
163	    /**
164	     * Fixed city-to-region lookup used to validate an owner's optional postcode against the region
165	     * derived from the owner's city. Any city not listed has region {@code 'UNKNOWN'} and so accepts
166	     * any 4-digit postcode.
167	     */
168	    private static final Map<String, String> CITY_REGION = Map.of(
