235	        owner.setHouseholdId(computeHouseholdId(owner.getLastName(), owner.getPostcode()));
236	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
237	        rejectDuplicateIdentity(owner);
238	        if (!sharesHousehold) {
239	            rejectHouseholdDuplicate(owner);
240	        }
241	        applyPossibleDuplicate(owner, sharesHousehold);
242	        owner.setRegistrationDate(registrationDate);
243	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
244	        owner.setCustomerCode(generateCustomerCode(owner.getPostcode(), owner.getTelephone(), owner.getLastName()));
245	        this.clinicService.saveOwner(owner);
246	        AUDIT.info("Owner created: id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
247	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
248	            owner.getMembershipLevel(), owner.getMembershipNumber());
