337	
338	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
339	    @Override
340	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
341	        Owner owner = this.clinicService.findOwnerById(ownerId);
342	        if (owner != null) {
343	            Pet pet = owner.getPet(petId);
344	            if (pet != null) {
345	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
346	            }
347	        }
348	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
349	    }
350	
351	    /**
352	     * Rejects an owner payload that is missing or blank in any required field. Bean Validation
353	     * already rejects {@code null} values and some formats, but a whitespace-only value can still
354	     * satisfy a {@code @Size(min = 1)} constraint; this guard catches those remaining cases.
355	     *
356	     * @param ownerFieldsDto the submitted owner fields
357	     * @throws InvalidOwnerFieldsException if any required field is missing or blank, carrying the
358	     *                                     name of every offending field
359	     */
