445	    /**
446	     * Normalizes a telephone number for owner creation into E.164 form. Spaces, dashes and brackets
447	     * are stripped. When the value carries a leading {@code '+'} the country code it supplies is kept;
448	     * otherwise the number is treated as a national Australian number, so a single leading {@code '0'}
449	     * is dropped and the {@code '+61'} country code is prepended. The result must be a {@code '+'}
450	     * followed by 8 to 15 digits. This E.164 string is what gets stored and returned.
451	     *
452	     * @param telephone the raw telephone value submitted by the client
453	     * @return the telephone in E.164 form, e.g. {@code +61412345678}
454	     * @throws InvalidOwnerFieldsException if the value cannot form a valid E.164 number, yielding a
455	     *                                     400 response
456	     */
457	    private String normalizeTelephone(String telephone) {
458	        String e164 = toE164(telephone);
459	        if (e164 == null) {
460	            throw new InvalidOwnerFieldsException(List.of("telephone"));
461	        }
462	        return e164;
463	    }
464	
465	    /**
466	     * Converts a raw telephone value to E.164 form, or returns {@code null} if it cannot form a valid
467	     * E.164 number. Spaces, dashes and brackets are removed; a leading {@code '+'} keeps the supplied
468	     * country code, while a bare national number has a single leading {@code '0'} dropped and the
469	     * {@code '+61'} country code prepended. A valid result is a {@code '+'} followed by 8 to 15 digits,
470	     * and when the supplied country code is one with a known national-number length
471	     * ({@link #NATIONAL_NUMBER_LENGTHS}, e.g. {@code '+61'} => 9, {@code '+1'} => 10) the national
472	     * number must have exactly that many digits.
473	     *
474	     * @param telephone the raw telephone value, possibly {@code null}
475	     * @return the E.164 string, or {@code null} if the value is not a valid E.164 number
476	     */
477	    private String toE164(String telephone) {
478	        if (telephone == null) {
479	            return null;
480	        }
481	        String cleaned = telephone.replaceAll("[\\s()\\-]", "");
482	        boolean hasPlus = cleaned.startsWith("+");
483	        String digits = (hasPlus ? cleaned.substring(1) : cleaned).replaceAll("\\D", "");
484	        String nationalSignificant = hasPlus
485	            ? digits
486	            : "61" + (digits.startsWith("0") ? digits.substring(1) : digits);
487	        if (!nationalSignificant.matches("[0-9]{8,15}")) {
488	            return null;
489	        }
490	        if (!hasValidNationalNumberLength(nationalSignificant)) {
491	            return null;
492	        }
493	        return "+" + nationalSignificant;
494	    }
495	
496	    /**
497	     * Checks the national-number length of an E.164 number (country code plus national significant
498	     * digits, no leading {@code '+'}) against the per-country requirement in
499	     * {@link #NATIONAL_NUMBER_LENGTHS}. The longest listed country code that prefixes the number
500	     * selects the requirement, and the remaining digits must number exactly that many. A number whose
501	     * country code is not listed carries no per-country length requirement and is accepted.
502	     *
503	     * @param nationalSignificant the digits of the E.164 number, country code first, without the
504	     *                            leading {@code '+'}
505	     * @return {@code true} if the national-number length is correct for the country code, or the
506	     *         country code has no listed requirement; {@code false} otherwise
507	     */
508	    private boolean hasValidNationalNumberLength(String nationalSignificant) {
509	        String countryCode = NATIONAL_NUMBER_LENGTHS.keySet().stream()
510	            .filter(nationalSignificant::startsWith)
511	            .max(Comparator.comparingInt(String::length))
512	            .orElse(null);
513	        if (countryCode == null) {
514	            return true;
515	        }
516	        int nationalLength = nationalSignificant.length() - countryCode.length();
517	        return nationalLength == NATIONAL_NUMBER_LENGTHS.get(countryCode);
518	    }
