520	    /**
521	     * Normalizes an optional owner email address. A {@code null} value means the field was omitted and
522	     * is left unset. When a value is present it must be a syntactically valid address whose domain is
523	     * not on the disposable-domain blocklist ({@link #DISPOSABLE_EMAIL_DOMAINS}); the stored and
524	     * returned value is that address lower-cased.
525	     *
526	     * @param email the raw email value submitted by the client, or {@code null} if omitted
527	     * @return the lower-cased email, or {@code null} if none was supplied
528	     * @throws InvalidOwnerFieldsException if a value is present but not a syntactically valid address,
529	     *                                     or its domain is a disposable-mail domain, yielding a 400
530	     *                                     response
531	     */
532	    private String normalizeEmail(String email) {
533	        if (email == null) {
534	            return null;
535	        }
536	        if (!EMAIL_PATTERN.matcher(email).matches()) {
537	            throw new InvalidOwnerFieldsException(List.of("email"));
