566	    /**
567	     * Builds the owner's {@code customerCode}, formatted {@code '<REGION>-<HASH8>'}. {@code REGION} is
568	     * the region code derived from the owner's postcode ({@link #regionForPostcode}, {@code 'UNKNOWN'}
569	     * when the postcode is absent or in no known range), and {@code HASH8} is the first eight
570	     * upper-cased hex characters of the SHA-256 digest of the owner's normalized telephone followed by
571	     * the last name (e.g. {@code 'NSW-1A2B3C4D'}). The identity carries no sequence number, so the
572	     * same postcode region, telephone and last name always yield the same customer code.
573	     *
574	     * <p>If the computed code collides with an existing owner's {@code customerCode}, it is
575	     * de-duplicated by appending {@code '-<n>'} with the smallest {@code n} of 2 or more that makes
576	     * it unique, so distinct owners always receive distinct customer codes.
577	     *
578	     * @param postcode  the owner's validated postcode, or {@code null} if none was supplied
579	     * @param telephone the owner's normalized (E.164) telephone
580	     * @param lastName  the owner's last name
581	     * @return the formatted, de-duplicated customer code
582	     */
583	    private String generateCustomerCode(String postcode, String telephone, String lastName) {
584	        String region = regionForPostcode(postcode);
585	        String hash8 = hashHex(telephone + lastName, 8);
586	        String baseCode = region + "-" + hash8;
587	        Set<String> existingCodes = this.clinicService.findAllOwners().stream()
588	            .map(Owner::getCustomerCode)
589	            .filter(Objects::nonNull)
590	            .collect(Collectors.toSet());
591	        if (!existingCodes.contains(baseCode)) {
592	            return baseCode;
593	        }
594	        int n = 2;
595	        while (existingCodes.contains(baseCode + "-" + n)) {
596	            n++;
597	        }
598	        return baseCode + "-" + n;
599	    }
