601	    /**
602	     * Resolves the region code for a postcode by its known 4-digit range in {@link #REGION_POSTCODES}
603	     * ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}), returning {@code 'UNKNOWN'}
604	     * when the postcode is {@code null}, not exactly 4 digits, or falls in no known range. This is the
605	     * {@code <REGION>} segment baked into the {@code customerCode}.
606	     *
607	     * @param postcode the owner's postcode, or {@code null}
608	     * @return the region code, or {@code 'UNKNOWN'}
609	     */
610	    private String regionForPostcode(String postcode) {
611	        if (postcode == null || !postcode.matches("[0-9]{4}")) {
612	            return "UNKNOWN";
613	        }
614	        int value = Integer.parseInt(postcode);
615	        for (Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
616	            int[] range = entry.getValue();
617	            if (value >= range[0] && value <= range[1]) {
618	                return entry.getKey();
619	            }
620	        }
621	        return "UNKNOWN";
622	    }
