624	    /**
625	     * Resolves the region code for a city via the fixed {@link #CITY_REGION} table
626	     * ({@code Sydney->NSW}, {@code Melbourne->VIC}, {@code Brisbane->QLD}), returning {@code 'UNKNOWN'}
627	     * when the city is not listed. Used to validate an owner's optional postcode against its city's
628	     * region.
629	     *
630	     * @param city the owner's city
631	     * @return the region code, or {@code 'UNKNOWN'}
632	     */
633	    private String regionForCity(String city) {
634	        return CITY_REGION.getOrDefault(city, "UNKNOWN");
635	    }
