637	    /**
638	     * Returns the first {@code length} upper-cased hex characters of the SHA-256 digest of the given
639	     * input. Used for the {@code <HASH8>} segment of a {@code customerCode} (length 8) and for the
640	     * deterministic {@code householdId} (length 12).
641	     *
642	     * @param input  the value to hash
643	     * @param length the number of leading hex characters to return
644	     * @return the first {@code length} upper-cased hex characters of its SHA-256 digest
645	     */
646	    private String hashHex(String input, int length) {
647	        try {
648	            byte[] digest = MessageDigest.getInstance("SHA-256")
649	                .digest(input.getBytes(StandardCharsets.UTF_8));
650	            StringBuilder hex = new StringBuilder(digest.length * 2);
651	            for (byte b : digest) {
652	                hex.append(String.format("%02x", b));
653	            }
654	            return hex.substring(0, length).toUpperCase(Locale.ROOT);
655	        } catch (NoSuchAlgorithmException e) {
656	            throw new IllegalStateException("SHA-256 algorithm not available", e);
657	        }
658	    }
