735	    /**
736	     * Rolls a registration date forward to a business day. A date that falls on a Saturday, a Sunday
737	     * or a listed {@linkplain #PUBLIC_HOLIDAYS public holiday} is rolled forward one day at a time
738	     * until it reaches the next non-holiday weekday; a date already on a non-holiday weekday is
739	     * returned unchanged. This applies to the effective registration date whether it was supplied in
740	     * the request or defaulted to the server date, and the adjusted value is what gets stored as
741	     * {@code registrationDate} and feeds every value derived from it (such as the membership number's
742	     * year segment and the daily create-limit's per-day bucket).
743	     *
744	     * @param date the effective registration date, supplied or defaulted
745	     * @return the same date when it is a non-holiday weekday, otherwise the next non-holiday business day
746	     */
747	    private LocalDate toBusinessDay(LocalDate date) {
748	        LocalDate adjusted = date;
749	        while (adjusted.getDayOfWeek() == DayOfWeek.SATURDAY
750	            || adjusted.getDayOfWeek() == DayOfWeek.SUNDAY
751	            || PUBLIC_HOLIDAYS.contains(adjusted)) {
752	            adjusted = adjusted.plusDays(1);
753	        }
754	        return adjusted;
755	    }
