783	    /**
784	     * Flags the owner being created as a possible (soft) duplicate. A possible duplicate is an owner
785	     * that is not a hard duplicate (its identity key is unique, so it has already passed
786	     * {@link #rejectDuplicateIdentity}) yet belongs to the same household as an existing owner — that
787	     * is, it carries the same computed {@code householdId} (derived from the last name and postcode) —
788	     * while carrying a different telephone. When such a match exists the owner is created with
789	     * {@code possibleDuplicate} set to {@code true} and {@code possibleDuplicateOf} set to the matching
790	     * owner's id (the earliest matching owner by id); otherwise {@code possibleDuplicate} is
791	     * {@code false} and {@code possibleDuplicateOf} is left unset.
792	     *
793	     * <p>An owner that declares household membership via {@code sharesHousehold} is never flagged: a
794	     * declared household member is not a suspected duplicate. (Without that declaration a same-household
795	     * owner is rejected outright by {@link #rejectHouseholdDuplicate}, so no suspected-duplicate match
796	     * survives for a created owner either.)
797	     *
798	     * @param owner           the owner being created, with its household id and telephone already set
799	     * @param sharesHousehold whether the owner declared itself a member of an existing household
800	     */
801	    private void applyPossibleDuplicate(Owner owner, boolean sharesHousehold) {
802	        owner.setPossibleDuplicate(false);
803	        if (sharesHousehold) {
804	            return;
805	        }
806	        String householdId = owner.getHouseholdId();
807	        if (householdId == null || householdId.isBlank()) {
808	            return;
809	        }
810	        String telephone = owner.getTelephone();
811	        Owner match = this.clinicService.findAllOwners().stream()
812	            .filter(this::isNotDeleted)
813	            .filter(existing -> householdId.equals(existing.getHouseholdId())
814	                && !Objects.equals(telephone, existing.getTelephone()))
815	            .min(Comparator.comparingInt(Owner::getId))
816	            .orElse(null);
817	        if (match != null) {
818	            owner.setPossibleDuplicate(true);
819	            owner.setPossibleDuplicateOf(match.getId());
820	        }
821	    }
