823	    /**
824	     * Computes the owner's deterministic {@code householdId}: the first twelve upper-cased hex
825	     * characters of the SHA-256 digest of the normalized last name and the postcode joined by a
826	     * {@code '|'}. Because the value derives only from the last name and postcode, every owner that
827	     * shares both automatically shares the same household id, so the household is keyed on
828	     * {@code (lastName, postcode)} with no opt-in required. The last name is normalized for comparison
829	     * (trimmed, internal whitespace collapsed, lower-cased) so values differing only in case or spacing
830	     * still land in the same household.
831	     *
832	     * @param lastName the owner's last name
833	     * @param postcode the owner's validated postcode, or {@code null} if none was supplied
834	     * @return the derived household id, or {@code null} when the owner has no postcode and so belongs
835	     *         to no postcode-keyed household
836	     */
837	    private String computeHouseholdId(String lastName, String postcode) {
838	        if (postcode == null) {
839	            return null;
840	        }
841	        return hashHex(normalizeForComparison(lastName) + "|" + postcode, 12);
842	    }
