844	    /**
845	     * Rejects creation of an owner that would join an existing household it has not declared membership
846	     * of. The household is keyed on the computed {@code householdId} (derived from the last name and
847	     * postcode), so any existing owner carrying the same {@code householdId} is a member of the same
848	     * household. A second owner in that household is a household duplicate and is rejected with a
849	     * {@code 409 Conflict} unless the request opts in via {@code sharesHousehold}, in which case this
850	     * check is bypassed and the owner is created as a declared household member. An owner with no
851	     * {@code householdId} (no postcode) belongs to no household and is never rejected here.
852	     *
853	     * @param owner the owner being created, with its household id already computed
854	     * @throws DuplicateHouseholdException if an existing owner already belongs to the same
855	     *                                     household, yielding a 409 Conflict response
856	     */
857	    private void rejectHouseholdDuplicate(Owner owner) {
858	        String householdId = owner.getHouseholdId();
859	        if (householdId == null || householdId.isBlank()) {
860	            return;
861	        }
862	        boolean inUse = this.clinicService.findAllOwners().stream()
863	            .filter(this::isNotDeleted)
864	            .anyMatch(existing -> householdId.equals(existing.getHouseholdId()));
865	        if (inUse) {
866	            throw new DuplicateHouseholdException(householdId);
867	        }
868	    }
869	
870	    /**
871	     * Normalizes a text value for case- and whitespace-insensitive comparison: surrounding
872	     * whitespace is trimmed, every internal run of whitespace is collapsed to a single space, and
873	     * the result is lower-cased.
874	     *
875	     * @param value the value to normalize, possibly {@code null}
876	     * @return the normalized value, or an empty string if {@code value} is {@code null}
877	     */
878	    private String normalizeForComparison(String value) {
879	        if (value == null) {
880	            return "";
881	        }
882	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
883	    }
884	
885	    /**
886	     * Normalizes an owner address for storage, display and comparison. Surrounding whitespace is
887	     * trimmed, every internal run of whitespace is collapsed to a single space, the value is
888	     * upper-cased, and common street-type abbreviations appearing as whole tokens are expanded
889	     * ({@code ST} to {@code STREET}, {@code RD} to {@code ROAD}, {@code AVE} to {@code AVENUE}).
890	     * This normalized value is what gets stored and returned.
891	     *
892	     * @param address the raw address value submitted by the client, possibly {@code null}
893	     * @return the normalized address, or an empty string if {@code address} is {@code null}
894	     */
895	    private String normalizeAddress(String address) {
896	        if (address == null) {
897	            return "";
898	        }
899	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
900	        if (collapsed.isEmpty()) {
901	            return collapsed;
902	        }
903	        String[] tokens = collapsed.split(" ");
904	        StringBuilder normalized = new StringBuilder(collapsed.length());
905	        for (int i = 0; i < tokens.length; i++) {
906	            if (i > 0) {
907	                normalized.append(' ');
908	            }
909	            normalized.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
910	        }
911	        return normalized.toString();
912	    }
913	
914	    /**
915	     * Reports whether the submitted owner supplies an address in either accepted form: a non-blank
916	     * structured {@code addressLine1}, or a non-blank flat {@code address}. The structured form is
917	     * preferred when present, but either satisfies the address requirement, keeping the create
918	     * contract backward-compatible with earlier flat-address-only owners.
919	     *
920	     * @param ownerFieldsDto the submitted owner fields
921	     * @return {@code true} if an address is supplied in either form
922	     */
923	    private boolean hasAddress(OwnerFieldsDto ownerFieldsDto) {
924	        return !isBlank(ownerFieldsDto.getAddressLine1())
925	            || !isBlank(normalizeAddress(ownerFieldsDto.getAddress()));
926	    }
927	
928	    /**
929	     * Applies the owner's address, preferring the structured form over the flat one. When a non-blank
930	     * {@code addressLine1} is supplied, it and the optional {@code addressLine2} are normalized
931	     * ({@link #normalizeAddress}) and stored, and the owner's composed {@code address} is set to the
932	     * normalized {@code addressLine1} with a single space and the normalized {@code addressLine2}
933	     * appended when {@code addressLine2} is present. Otherwise the flat {@code address} is normalized
934	     * and stored and the structured lines are left unset. This keeps earlier flat-address owners
935	     * working while letting everything that reads the address use the composed, normalized value.
936	     *
937	     * @param owner          the owner being created
938	     * @param ownerFieldsDto the submitted owner fields
939	     */
940	    private void applyAddress(Owner owner, OwnerFieldsDto ownerFieldsDto) {
941	        if (!isBlank(ownerFieldsDto.getAddressLine1())) {
942	            String line1 = normalizeAddress(ownerFieldsDto.getAddressLine1());
943	            String line2 = isBlank(ownerFieldsDto.getAddressLine2())
944	                ? null
945	                : normalizeAddress(ownerFieldsDto.getAddressLine2());
946	            owner.setAddressLine1(line1);
947	            owner.setAddressLine2(line2);
948	            owner.setAddress(line2 != null ? line1 + " " + line2 : line1);
949	        } else {
950	            owner.setAddressLine1(null);
951	            owner.setAddressLine2(null);
952	            owner.setAddress(normalizeAddress(ownerFieldsDto.getAddress()));
953	        }
954	    }
955	}
